package cn.zj.zjmarket.verification;
import cn.zj.zjmarket.domain.reconciliation.model.Reconciliation.*;
import cn.zj.zjmarket.domain.reconciliation.adapter.port.IReconciliationPort;
import cn.zj.zjmarket.domain.reconciliation.service.ReconciliationService;
import cn.zj.zjmarket.infrastructure.adapter.repository.ReconciliationRepository;
import cn.zj.zjmarket.domain.order.service.*;
import cn.zj.zjmarket.domain.order.model.valobj.*;
import cn.zj.zjmarket.domain.payment.service.IPaymentService;
import cn.zj.zjmarket.domain.payment.adapter.repository.*;
import cn.zj.zjmarket.domain.payment.adapter.port.*;
import cn.zj.zjmarket.infrastructure.adapter.port.payment.RocketMqSettlementTransport;
import cn.zj.zjmarket.domain.product.service.IMarketingTrialService;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.context.ConfigurableApplicationContext;
import org.springframework.jdbc.core.JdbcTemplate;
import java.nio.file.*;
import java.util.*;
import static cn.zj.zjmarket.verification.SyncCommands.check;

/** Actual A/TLS/MQ with complete B-owned roster. Only response loss is injected here. */
public final class ActualReconciliationCommands {
 private static final ObjectMapper JSON=new ObjectMapper();
 private static String id(){return UUID.randomUUID().toString();}
 public static void run(ConfigurableApplicationContext ctx,Path work,String mode)throws Exception{
  var db=new JdbcTemplate(ctx.getBean(javax.sql.DataSource.class));var repo=ctx.getBean(ReconciliationRepository.class);var rpc=ctx.getBean(IReconciliationPort.class);var store=ctx.getBean(ISettlementRepository.class);var facts=(IChannelFacts)ctx.getBean(ISimulatedChannel.class);var orders=ctx.getBean(IOrderService.class);var manifest=work.resolve("reconciliation-restart.json");
  if(mode.equals("reconciliation-recover")){
   var f=JSON.readTree(Files.readAllBytes(manifest));String task=f.path("task").asText(),team=f.path("team").asText(),paidOrder=f.path("paidOrder").asText();boolean none=f.path("paymentCase").asText().equals("NONE");var service=ctx.getBean(ReconciliationService.class);drive(service,db,task,12);
   check("RESOLVED".equals(db.queryForObject("SELECT state FROM b_reconciliation_task WHERE task_id=?",String.class,task)),"actual A original completion recovered in new JVM");
   check(f.path("hash").asText().equals(db.queryForObject("SELECT request_hash FROM b_reconciliation_submission WHERE task_id=?",String.class,task)),"same completionId/checkedAt/request bytes across actual A replay");
   check(rpc.team(team).status().equals("FAILED"),"actual A terminal FAILED");
   if(!none){check(db.queryForObject("SELECT COUNT(*) FROM b_refund WHERE order_id=? AND eligibility_status='ELIGIBLE' AND funds_status='NONE'",Long.class,paidOrder)==1,"one eligible full refund obligation without execution");check(db.queryForObject("SELECT state FROM b_inventory_reservation WHERE order_id=?",String.class,paidOrder).equals("HELD"),"paid member retains HELD");}
   check(db.queryForObject("SELECT COUNT(*) FROM b_inventory_ledger l JOIN b_reconciliation_member m ON m.out_trade_no=l.order_id WHERE m.task_id=? AND l.kind='RELEASE'",Long.class,task)==(none?3:2),"all original unpaid releases exactly once");
   var owned=new ArrayList<String>();f.path("members").forEach(x->owned.add(x.asText()));if(none)for(String oid:owned)check(db.queryForObject("SELECT COUNT(*) FROM b_payment WHERE order_id=? AND funds_state='SUCCEEDED'",Long.class,oid)==0&&db.queryForObject("SELECT COUNT(*) FROM b_refund WHERE order_id=?",Long.class,oid)==0,"unpaid actual roster has no payment/refund");B05Conservation.capture(db,owned,work,mode);
   Files.writeString(work.resolve(mode+".txt"),"status=PASSED\nactual-A/TLS/new-JVM/original-completion-replay/FAILED/unpaid-unique-release=PASSED\npaymentCase="+(none?"NONE":"PARTIAL")+"\n");return;
  }
  var f=JSON.readTree(Files.readAllBytes(work.resolve("fixtures.json")));var restart=JSON.readTree(Files.readAllBytes(work.resolve("trade-restart.json")));String actor=f.path("users").path("USER").asText(),openId=restart.path("openOrderId").asText();var open=orders.detail(actor,openId);var members=new ArrayList<String>();members.add(openId);var worker=ctx.getBean(ITradeCoordinationService.class);
  for(String role:List.of("MEMBER","SECOND")){String u=f.path("users").path(role).asText();var offer=ctx.getBean(IMarketingTrialService.class).trial(u,open.confirmation().conditions().goodsId(),id()).offer();var c=orders.confirm(u,new PurchaseConditions(open.confirmation().conditions().goodsId(),"JOIN",open.evidence().teamId(),offer),id());var m=orders.create(u,id(),c.confirmationId(),id()).order();worker.recover(m.orderId());check(orders.detail(u,m.orderId()).businessStatus().equals("WAITING_PAYMENT"),"actual B owned JOIN");members.add(m.orderId());}
  boolean completing=mode.equals("reconciliation-completed");boolean none="NONE".equals(System.getenv("B05_RECONCILIATION_PAYMENT_CASE"));check(!completing||!none,"all-paid competition and none are separate batches");var payments=ctx.getBean(IPaymentService.class);var pay=ctx.getBean(IPaymentRepository.class);var transport=ctx.getBean(RocketMqSettlementTransport.class);transport.start();var deliveries=new ArrayList<cn.zj.zjmarket.domain.payment.model.valobj.TradeDelivery>();var paymentIds=new ArrayList<String>();
  for(String member:completing?members:none?List.<String>of():List.of(openId)){String user=db.queryForObject("SELECT user_id FROM b_market_order WHERE order_id=?",String.class,member);var current=orders.detail(user,member);long safeAt=ReservationEvidence.instant(current.evidence().reservedAt())+2500;while(pay.now()<safeAt)Thread.sleep(50);var created=payments.create(user,member,id(),null,id());String payment=created.receipt().paymentId(),attempt=created.receipt().attemptId();paymentIds.add(payment);ReconciliationCommands.payOwned(ctx,pay,ctx.getBean(ISimulatedChannel.class),user,payment);payments.choose(user,payment,attempt,id(),"SUCCEEDED",id());ReconciliationCommands.payOwned(ctx,pay,ctx.getBean(ISimulatedChannel.class),user,payment);store.observe(facts.fact(payment,attempt));String event=db.queryForObject("SELECT event_id FROM b_trade_outbox WHERE payment_id=?",String.class,payment);var delivery=store.claim(event);check(delivery!=null,"owned payment Outbox claim");deliveries.add(delivery);if(!completing||deliveries.size()<3){transport.publish(delivery);store.delivered(delivery,true,null);}}
  SyncCommands.waitFor(()->{store.applyInbox(100);return db.queryForObject("SELECT COUNT(*) FROM b_payment WHERE order_id IN (?,?,?) AND a_acceptance='ACCEPTED'",Long.class,members.get(0),members.get(1),members.get(2))==(completing?2L:none?0L:1L);},45000,"actual A accepted original payment before expiry");
  String team=open.evidence().teamId();SyncCommands.waitFor(()->rpc.team(team).status().equals("RECONCILING"),150000,"natural A expiry and frozen complete roster");
  String task=id();db.update("INSERT INTO b_reconciliation_task(task_id,source,channel,team_id,next_attempt_ms,created_at_ms,updated_at_ms) VALUES(?,'s01','c01',?,0,0,0)",task,team);
  if(completing){var service=ctx.getBean(ReconciliationService.class);drive(service,db,task,3);check(db.queryForObject("SELECT COUNT(*) FROM b_order_block WHERE owner_id=? AND state='ACTIVE'",Long.class,team)>0,"reconciliation owns temporary blocks before last accepted payment");var last=store.claim(deliveries.getLast().eventId());check(last!=null,"fresh original Outbox lease after natural expiry");transport.publish(last);store.delivered(last,true,null);SyncCommands.waitFor(()->{store.applyInbox(100);return rpc.team(team).status().equals("COMPLETED")&&db.queryForObject("SELECT COUNT(*) FROM b_trade_work WHERE team_id=? AND kind='TEAM_COMPLETED'",Long.class,team)==3;},60000,"late delivery of original in-window payment completes actual reconciling A team");drive(service,db,task,8);check(db.queryForObject("SELECT state FROM b_reconciliation_task WHERE task_id=?",String.class,task).equals("RESOLVED"),"COMPLETED wins reconciliation");var fulfillment=ctx.getBean(IFulfillmentRepository.class);for(String member:members){String user=db.queryForObject("SELECT user_id FROM b_market_order WHERE order_id=?",String.class,member);check(!orders.detail(user,member).reviewRequired(),"only own temporary review cleared");String wid=db.queryForObject("SELECT work_id FROM b_trade_work WHERE kind='TEAM_COMPLETED' AND order_id=?",String.class,member);db.update("UPDATE b_trade_work SET next_attempt_ms=0 WHERE work_id=?",wid);var claimed=fulfillment.claim(wid);check(claimed!=null,"original fulfillment claim after temporary block clears");fulfillment.complete(claimed,transport.queryTrade(claimed.payment()));check(orders.detail(user,member).businessStatus().equals("GROUP_COMPLETED")&&fulfillment.summary(user,member).get("status").equals("PENDING"),"actual original fulfillment CONFIRM/PENDING");check(db.queryForObject("SELECT COUNT(*) FROM b_refund WHERE order_id=?",Long.class,member)==0&&db.queryForObject("SELECT COUNT(*) FROM b_inventory_ledger WHERE order_id=? AND kind='RELEASE'",Long.class,member)==0&&db.queryForObject("SELECT COUNT(*) FROM b_inventory_ledger WHERE order_id=? AND kind='CONFIRM'",Long.class,member)==1,"completed member no refund or release and exactly one confirm");}B05Conservation.capture(db,members,work,mode);Files.writeString(work.resolve(mode+".txt"),"status=PASSED\nactual-A/natural-RECONCILING/original-in-window-last-payment/COMPLETED/own-block-clear/three-CONFIRM/three-PENDING/no-refund/no-RELEASE=PASSED\n");return;}
  var lossy=new IReconciliationPort(){boolean lost;public Team team(String id){return rpc.team(id);}public Roster roster(String id){return rpc.roster(id);}public Trade trade(cn.zj.zjmarket.domain.order.model.entity.MarketOrder o){return rpc.trade(o);}public Result complete(Completion c){var result=rpc.complete(c);if(!lost){lost=true;throw new IllegalStateException("verification-only actual A committed response lost");}return result;}};
  var service=new ReconciliationService(repo,lossy,facts,store);for(int i=0;i<40;i++){drive(service,db,task,1);String state=db.queryForObject("SELECT state FROM b_reconciliation_task WHERE task_id=?",String.class,task);if(state.equals("SUBMIT_UNKNOWN"))break;check(!state.equals("REVIEW_REQUIRED"),"actual A evidence must not conflict");Thread.sleep(100);}
  check(db.queryForObject("SELECT COUNT(*) FROM b_reconciliation_member WHERE task_id=?",Long.class,task)==3,"exact full three B-member roster");
  check("SUBMIT_UNKNOWN".equals(db.queryForObject("SELECT state FROM b_reconciliation_task WHERE task_id=?",String.class,task)),"actual A commit then lost response persists unknown");String hash=db.queryForObject("SELECT request_hash FROM b_reconciliation_submission WHERE task_id=?",String.class,task);
  Files.writeString(manifest,JSON.writeValueAsString(Map.of("task",task,"team",team,"paidOrder",none?"":openId,"hash",hash,"members",members,"paymentCase",none?"NONE":"PARTIAL")));
  Files.writeString(work.resolve(mode+".txt"),"status=PASSED\nactual-A/TLS/signed-MQ/three-B-owned-members/natural-expiry/full-roster/original-close/commit-response-loss=PASSED\n");
 }
 private static void drive(ReconciliationService service,JdbcTemplate db,String task,int times){for(int i=0;i<times;i++){db.update("UPDATE b_reconciliation_task SET next_attempt_ms=0 WHERE task_id=?",task);for(String order:db.queryForList("SELECT out_trade_no FROM b_reconciliation_member WHERE task_id=?",String.class,task))db.update("UPDATE b_trade_coordination SET next_attempt_ms=0 WHERE order_id=?",order);service.recover(task);}}
}
